:root {
  --ink: #f2f7ff;
  --ink-dim: #a9b6d0;
  --bg: #070a15;
  --panel: rgba(11, 17, 34, 0.72);
  --line: rgba(146, 180, 255, 0.16);
  --cyan: #41f6ff;
  --cyan-soft: #8cfbff;
  --magenta: #ff3d9a;
  --orange: #ff9d4d;
  --lime: #b8ff63;
  --red: #ff4d5e;
  --violet: #8b7dff;
  --font-display: "Arial Black", "Helvetica Neue", Impact, system-ui, sans-serif;
  --font-ui: "Inter", "Helvetica Neue", Arial, system-ui, sans-serif;
  --font-mono: ui-monospace, "SFMono-Regular", "Cascadia Code", Menlo, Consolas, monospace;
  --sat: env(safe-area-inset-top, 0px);
  --sar: env(safe-area-inset-right, 0px);
  --sab: env(safe-area-inset-bottom, 0px);
  --sal: env(safe-area-inset-left, 0px);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font-ui);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}

body {
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
}

canvas#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
}

.hidden { display: none !important; }

button {
  font-family: inherit;
  color: inherit;
  border: 0;
  background: none;
  cursor: pointer;
  touch-action: manipulation;
}

button:focus-visible {
  outline: 2px solid var(--cyan);
  outline-offset: 3px;
}

/* ---------- screen texture ---------- */
.screen-fx {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 5;
  background:
    radial-gradient(ellipse at 50% 48%, transparent 38%, rgba(2, 4, 10, 0.42) 78%, rgba(2, 4, 10, 0.78) 100%),
    repeating-linear-gradient(to bottom, rgba(255, 255, 255, 0.022) 0 1px, transparent 1px 3px);
  mix-blend-mode: normal;
  opacity: 0.9;
}

.flash {
  position: absolute;
  inset: 0;
  background: white;
  opacity: 0;
  pointer-events: none;
  z-index: 40;
  transition: opacity 120ms ease-out;
}

/* ---------- HUD ---------- */
.hud {
  position: absolute;
  inset: 0;
  z-index: 20;
  pointer-events: none;
  padding: calc(16px + var(--sat)) calc(18px + var(--sar)) calc(14px + var(--sab)) calc(18px + var(--sal));
}

.hud-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
}

.player-card {
  display: flex;
  gap: 10px;
  align-items: center;
  min-width: min(380px, 42vw);
  padding: 9px 14px 10px 10px;
  border: 1px solid var(--line);
  border-left: 2px solid var(--cyan);
  border-radius: 4px 14px 14px 4px;
  background: linear-gradient(100deg, rgba(8, 14, 28, 0.88), rgba(8, 14, 28, 0.28));
  backdrop-filter: blur(8px);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.28), inset 0 0 24px rgba(65, 246, 255, 0.04);
}

.avatar {
  position: relative;
  width: 48px;
  height: 48px;
  flex: 0 0 48px;
  border-radius: 10px;
  border: 1px solid rgba(65, 246, 255, 0.34);
  background: radial-gradient(circle at 50% 32%, rgba(65, 246, 255, 0.2), rgba(6, 10, 22, 0.9) 70%);
  overflow: hidden;
}

.avatar canvas { width: 100%; height: 100%; display: block; }

.avatar-tag {
  position: absolute;
  right: 2px;
  bottom: 1px;
  font-family: var(--font-mono);
  font-size: 8px;
  letter-spacing: 0.12em;
  color: var(--cyan);
  opacity: 0.75;
}

.bars { flex: 1; min-width: 0; }

.bar-labels {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.14em;
  color: var(--ink-dim);
  margin-bottom: 3px;
}

.bar-labels:first-child .fighter-name { color: var(--ink); letter-spacing: 0.22em; font-weight: 700; }
#hpText { color: var(--ink); font-size: 11px; }

.bar {
  position: relative;
  height: 9px;
  overflow: hidden;
  border-radius: 2px;
  background: rgba(255, 255, 255, 0.08);
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.55);
}

.hp-track { height: 11px; margin-bottom: 6px; }

.hp-ghost, .hp-fill {
  position: absolute;
  inset: 0 auto 0 0;
  width: 100%;
  transform-origin: left center;
}

.hp-ghost { background: rgba(255, 77, 94, 0.55); transition: width 420ms cubic-bezier(0.2, 0.7, 0.2, 1); }
.hp-fill {
  background: linear-gradient(90deg, #37ffb0, var(--lime));
  box-shadow: 0 0 12px rgba(184, 255, 99, 0.5);
  transition: width 110ms linear;
}
.hp-fill.low { background: linear-gradient(90deg, #ff4d5e, #ff9d4d); box-shadow: 0 0 14px rgba(255, 77, 94, 0.55); }

.rage-labels { margin-top: 1px; font-size: 9px; }
.rage-hint { color: var(--cyan); opacity: 0.7; }
.rage-hint.ready { animation: glowPulse 1.1s ease-in-out infinite; opacity: 1; }
.rage-track { height: 6px; }
.rage-fill {
  position: absolute;
  inset: 0 auto 0 0;
  width: 0%;
  background: linear-gradient(90deg, var(--violet), var(--magenta) 52%, var(--orange));
  box-shadow: 0 0 12px rgba(255, 61, 154, 0.5);
  transition: width 130ms linear;
}

.wave-chip {
  display: flex;
  align-items: baseline;
  gap: 6px;
  padding: 7px 14px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(8, 13, 28, 0.64);
  backdrop-filter: blur(8px);
  font-family: var(--font-mono);
  white-space: nowrap;
}

.wave-kicker { font-size: 9px; letter-spacing: 0.22em; color: var(--ink-dim); }
.wave-num { font-size: 20px; font-weight: 800; color: var(--cyan); line-height: 1; }
.wave-total { font-size: 10px; color: var(--ink-dim); }

.score-card {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
  padding: 7px 10px 7px 14px;
  border: 1px solid var(--line);
  border-right: 2px solid var(--magenta);
  border-radius: 12px 4px 4px 12px;
  background: linear-gradient(260deg, rgba(8, 14, 28, 0.88), rgba(8, 14, 28, 0.25));
  backdrop-filter: blur(8px);
  min-width: 156px;
}

.score-line {
  display: flex;
  align-items: baseline;
  gap: 10px;
  width: 100%;
  justify-content: space-between;
  font-family: var(--font-mono);
  font-size: 17px;
  font-weight: 700;
  letter-spacing: 0.04em;
  line-height: 1.2;
}

.score-line.best { font-size: 11px; color: var(--ink-dim); }
.score-kicker { font-size: 8px; letter-spacing: 0.18em; color: var(--ink-dim); }

.hud-buttons {
  display: flex;
  gap: 6px;
  margin-top: 5px;
  pointer-events: auto;
}

.icon-btn {
  width: 28px;
  height: 26px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.04);
  font-size: 11px;
  line-height: 1;
  color: var(--ink);
  transition: background 140ms, border-color 140ms;
}
.icon-btn:hover { background: rgba(65, 246, 255, 0.12); border-color: rgba(65, 246, 255, 0.4); }

#combo {
  position: absolute;
  top: calc(88px + var(--sat));
  right: calc(20px + var(--sar));
  text-align: right;
  font-family: var(--font-display);
  font-style: italic;
  color: var(--orange);
  text-shadow: 0 0 24px rgba(255, 157, 77, 0.45), 3px 3px 0 rgba(0, 0, 0, 0.4);
  transform-origin: top right;
  line-height: 0.86;
  letter-spacing: -0.04em;
}

#comboCount { font-size: clamp(44px, 6vw, 74px); }
.combo-x {
  display: block;
  font-family: var(--font-mono);
  font-size: 10px;
  font-style: normal;
  letter-spacing: 0.36em;
  color: var(--ink);
  opacity: 0.75;
  margin-top: 5px;
}
.combo-rank {
  font-family: var(--font-mono);
  font-size: 11px;
  font-style: normal;
  letter-spacing: 0.2em;
  color: var(--magenta);
  margin-top: 2px;
  min-height: 14px;
}
#combo.pop { animation: comboPop 260ms cubic-bezier(0.1, 1.6, 0.3, 1); }

.boss-bar {
  position: absolute;
  top: calc(74px + var(--sat));
  left: 50%;
  width: min(520px, 56vw);
  transform: translateX(-50%);
  padding: 8px 12px 10px;
  border: 1px solid rgba(255, 61, 154, 0.28);
  border-radius: 8px;
  background: rgba(9, 13, 27, 0.72);
  backdrop-filter: blur(8px);
  box-shadow: 0 0 34px rgba(255, 61, 154, 0.12);
}

.boss-head {
  display: flex;
  justify-content: space-between;
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: 0.22em;
  color: #ffc2df;
  margin-bottom: 4px;
}
.boss-head span:first-child { color: var(--magenta); font-weight: 700; }
.boss-track { height: 10px; }
.boss-fill {
  position: absolute;
  inset: 0 auto 0 0;
  width: 100%;
  background: linear-gradient(90deg, #8b1c54, var(--magenta), #ff8a3d);
  box-shadow: 0 0 16px rgba(255, 61, 154, 0.55);
  transition: width 120ms linear;
}

/* ---------- banner ---------- */
.banner {
  position: absolute;
  top: 27%;
  left: 50%;
  transform: translate(-50%, -50%) skewX(-4deg);
  z-index: 26;
  text-align: center;
  pointer-events: none;
  opacity: 0;
  width: 100%;
  padding: 0 20px;
}

.banner.show { animation: bannerIn 2.2s cubic-bezier(0.16, 0.9, 0.24, 1) both; }
.banner-main {
  font-family: var(--font-display);
  font-style: italic;
  font-size: clamp(34px, 5.8vw, 74px);
  line-height: 0.95;
  letter-spacing: -0.02em;
  color: var(--ink);
  text-shadow: 0 0 30px rgba(65, 246, 255, 0.5), 0 5px 0 rgba(0, 0, 0, 0.35);
}
.banner-main em { color: var(--cyan); font-style: italic; }
.banner-sub {
  font-family: var(--font-mono);
  font-size: clamp(10px, 1.3vw, 13px);
  letter-spacing: 0.42em;
  color: var(--magenta);
  margin-top: 8px;
  text-transform: uppercase;
}
.banner.gold .banner-main { color: #ffe6a1; text-shadow: 0 0 34px rgba(255, 190, 80, 0.6); }
.banner.gold .banner-sub { color: var(--orange); }

.hint {
  position: absolute;
  left: 50%;
  bottom: calc(20px + var(--sab));
  transform: translateX(-50%);
  z-index: 19;
  display: flex;
  gap: 8px;
  align-items: center;
  flex-wrap: wrap;
  justify-content: center;
  padding: 8px 16px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(7, 11, 24, 0.7);
  backdrop-filter: blur(8px);
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.06em;
  color: var(--ink-dim);
  pointer-events: none;
  animation: hintFade 9s ease both;
}
.hint-key {
  color: var(--cyan);
  border: 1px solid rgba(65, 246, 255, 0.3);
  border-radius: 3px;
  padding: 1px 4px;
  font-size: 9px;
}

/* ---------- overlays ---------- */
.overlay {
  position: absolute;
  inset: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.title-overlay {
  align-items: stretch;
  justify-content: flex-start;
  background: linear-gradient(92deg, rgba(3, 6, 15, 0.94) 0%, rgba(3, 6, 15, 0.82) 38%, rgba(3, 6, 15, 0.32) 68%, rgba(3, 6, 15, 0.14) 100%);
}

.title-fade {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse at 16% 46%, rgba(65, 246, 255, 0.08), transparent 44%),
    radial-gradient(ellipse at 82% 66%, rgba(255, 61, 154, 0.08), transparent 42%);
}

.menu-shell {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: center;
  width: min(650px, 64vw);
  padding: max(28px, calc(24px + var(--sat))) 0 calc(20px + var(--sab)) max(7vw, calc(24px + var(--sal)));
  z-index: 1;
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-mono);
  font-size: clamp(8px, 0.85vw, 10px);
  letter-spacing: 0.28em;
  color: var(--ink-dim);
  margin-bottom: 14px;
  animation: riseIn 700ms 120ms both;
}
.eyebrow .dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--magenta);
