import { TAU, clamp, rand, pick, easeOutCubic } from './utils.js';

export class Particles {
  constructor(limit = 520) {
    this.list = [];
    this.texts = [];
    this.limit = limit;
  }

  clear() {
    this.list.length = 0;
    this.texts.length = 0;
  }

  add(p) {
    if (this.list.length >= this.limit) this.list.shift();
    this.list.push({
      x: 0, y: 0.5, z: 0,
      vx: 0, vy: 0, vz: 0,
      life: 0.5, maxLife: 0.5,
      size: 2, grow: 0,
      color: '#ffffff', type: 'spark',
      gravity: 0, drag: 2,
      rot: 0, vr: 0,
      alpha: 1, additive: true,
      width: 2,
      ...p,
    });
  }

  burst(x, y, z, opts = {}) {
    const {
      count = 10,
      speed = 220,
      spread = TAU,
      angle = 0,
      colors = ['#ffffff'],
      size = [2, 4],
      life = [0.2, 0.5],
      gravity = 900,
      drag = 3,
      type = 'spark',
      additive = true,
      grow = 0,
      zSpread = 0.5,
      width = [1.5, 3],
    } = opts;
    for (let i = 0; i < count; i++) {
      const a = angle + rand(-spread / 2, spread / 2);
      const s = speed * rand(0.3, 1.1);
      const l = rand(life[0], life[1]);
      this.add({
        x, y, z,
        vx: Math.cos(a) * s,
        vy: rand(-0.25, 0.25) * s * zSpread,
        vz: Math.sin(a) * s * (type === 'dust' ? 0.3 : 0.85),
        life: l, maxLife: l,
        size: rand(size[0], size[1]),
        grow,
        color: pick(colors),
        type,
        gravity,
        drag,
        additive,
        width: rand(width[0], width[1]),
        rot: rand(0, TAU),
        vr: rand(-12, 12),
      });
    }
  }

  dust(x, y, count = 6, color = 'rgba(170, 190, 220, 0.5)') {
    for (let i = 0; i < count; i++) {
      const a = rand(-Math.PI, 0);
      const s = rand(40, 130);
      const l = rand(0.25, 0.6);
      this.add({
        x: x + rand(-16, 16), y, z: rand(0, 8),
        vx: Math.cos(a) * s,
        vy: rand(-0.02, 0.02),
        vz: rand(30, 110),
        life: l, maxLife: l,
        size: rand(4, 11), grow: 22,
        color, type: 'dust', gravity: -10, drag: 2.5,
        additive: false, alpha: 0.55,
      });
    }
  }

  ring(x, y, z, color, size = 18, life = 0.3, grow = 240) {
    this.add({
      x, y, z, life, maxLife: life, size, grow,
      color, type: 'ring', gravity: 0, drag: 0,
      additive: true, width: 3,
    });
  }

  text(x, y, z, text, opts = {}) {
    const life = opts.life ?? 0.8;
    this.texts.push({
      x, y, z, text,
      life, maxLife: life,
      vy: opts.vy ?? -0.9,
      color: opts.color ?? '#ffffff',
      size: opts.size ?? 22,
      font: opts.font ?? 'display',
      italic: opts.italic ?? true,
      shadow: opts.shadow ?? true,
      drift: opts.drift ?? rand(-0.15, 0.15),
      rot: opts.rot ?? rand(-0.05, 0.05),
    });
    if (this.texts.length > 24) this.texts.shift();
  }

  update(dt) {
    for (let i = this.list.length - 1; i >= 0; i--) {
      const p = this.list[i];
      p.life -= dt;
      if (p.life <= 0) { this.list.splice(i, 1); continue; }
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.z += p.vz * dt;
      p.vz -= p.gravity * dt;
      const drag = Math.exp(-p.drag * dt);
      p.vx *= drag;
      p.vy *= drag;
      p.vz *= drag;
      p.rot += p.vr * dt;
      p.size = Math.max(0.1, p.size + p.grow * dt);
      if (p.z < 0) {
        p.z = 0;
        p.vz *= -0.32;
        p.vx *= 0.7;
        if (Math.abs(p.vz) < 12) p.vz = 0;
      }
    }
    for (let i = this.texts.length - 1; i >= 0; i--) {
      const t = this.texts[i];
      t.life -= dt;
      if (t.life <= 0) { this.texts.splice(i, 1); continue; }
      t.age = (t.age || 0) + dt;
      t.y += t.vy * dt * 0.05;
      t.z += Math.abs(t.vy) * 55 * dt;
      t.x += t.drift * dt * 10;
    }
  }

  draw(ctx, project) {
    ctx.save();
    for (const p of this.list) {
      const { sx, sy, s } = project(p.x, p.y, p.z);
      const k = clamp(p.life / p.maxLife, 0, 1);
      ctx.globalAlpha = k * p.alpha;
      ctx.globalCompositeOperation = p.additive ? 'lighter' : 'source-over';
      ctx.fillStyle = p.color;
      ctx.strokeStyle = p.color;
      if (p.type === 'ring') {
        ctx.beginPath();
        ctx.arc(sx, sy, Math.max(0.5, p.size * s), 0, TAU);
        ctx.lineWidth = Math.max(0.5, p.width * s * k);
        ctx.stroke();
      } else if (p.type === 'spark') {
        const vx = p.vx * 0.03 * s;
        const vy = (-p.vz * 0.03 + p.vy * 10) * s;
        ctx.beginPath();
        ctx.moveTo(sx, sy);
        ctx.lineTo(sx - vx, sy - vy);
        ctx.lineWidth = Math.max(0.7, p.width * s * (0.4 + k * 0.8));
        ctx.stroke();
      } else if (p.type === 'shard') {
        const size = p.size * s;
        ctx.save();
        ctx.translate(sx, sy);
        ctx.rotate(p.rot);
        ctx.fillRect(-size / 2, -size / 6, size, size / 3);
        ctx.restore();
      } else if (p.type === 'dust') {
        ctx.globalAlpha = k * p.alpha * 0.55;
        ctx.beginPath();
        ctx.arc(sx, sy, Math.max(0.5, p.size * s), 0, TAU);
        ctx.fill();
      } else {
        ctx.beginPath();
        ctx.arc(sx, sy, Math.max(0.6, p.size * s), 0, TAU);
        ctx.fill();
      }
    }
    ctx.globalCompositeOperation = 'source-over';
    ctx.restore();
  }

  drawTexts(ctx, project) {
    ctx.save();
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    for (const t of this.texts) {
      const { sx, sy, s } = project(t.x, t.y, t.z);
      const k = clamp(t.life / t.maxLife, 0, 1);
      const pop = t.age < 0.12 ? easeOutCubic(t.age / 0.12) : 1;
      const size = t.size * s * (0.7 + pop * 0.3) * (1 + (1 - k) * 0.12);
      ctx.globalAlpha = Math.min(1, k * 1.6);
      ctx.font = t.font === 'mono'
        ? `700 ${size}px ui-monospace, Menlo, monospace`
        : `italic 900 ${size}px "Arial Black", "Helvetica Neue", sans-serif`;
      if (t.shadow) {
        ctx.shadowColor = t.color;
        ctx.shadowBlur = 12 * s;
      }
      ctx.fillStyle = t.color;
      if (t.italic) {
        ctx.save();
        ctx.translate(sx, sy);
        ctx.rotate(t.rot);
        ctx.fillText(t.text, 0, 0);
        ctx.restore();
      } else {
        ctx.fillText(t.text, sx, sy);
      }
      ctx.shadowBlur = 0;
    }
    ctx.restore();
  }
}

import { TAU, clamp, lerp } from './utils.js';

export function makePose() {
  return {
    hipX: 0,
    bob: 0,
    torso: 0.06,
    headTilt: 0,
    armFar: [0.16, 0.32],
    armNear: [0.09, 0.28],
    legFar: [0.1, 0.11],
    legNear: [-0.1, 0.09],
  };
}

export function clonePose(p) {
  return {
    hipX: p.hipX,
    bob: p.bob,
    torso: p.torso,
    headTilt: p.headTilt,
    armFar: [p.armFar[0], p.armFar[1]],
    armNear: [p.armNear[0], p.armNear[1]],
    legFar: [p.legFar[0], p.legFar[1]],
    legNear: [p.legNear[0], p.legNear[1]],
  };
}

export function blendPose(pose, target, dt, speed = 20) {
  const k = 1 - Math.exp(-speed * dt);
  pose.hipX = lerp(pose.hipX, target.hipX, k);
  pose.bob = lerp(pose.bob, target.bob, k);
  pose.torso = lerp(pose.torso, target.torso, k);
  pose.headTilt = lerp(pose.headTilt, target.headTilt, k);
  for (const key of ['armFar', 'armNear', 'legFar', 'legNear']) {
    pose[key][0] = lerp(pose[key][0], target[key][0], k);
    pose[key][1] = lerp(pose[key][1], target[key][1], k);
  }
}

function strokePath(ctx, points, width, color, alpha) {
  if (alpha <= 0.003) return;
  ctx.globalAlpha = alpha;
  ctx.strokeStyle = color;
  ctx.lineWidth = width;
  ctx.beginPath();
  ctx.moveTo(points[0][0], points[0][1]);
  for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
  ctx.stroke();
}

/**
 * Draws a procedural stick figure.
 * Local space: feet at (0,0), 1 unit ≈ body height, +y is down.
 */
export function drawStickman(ctx, opts) {
  const {
    x, y, scale, facing = 1, pose, rot = 0,
    colors = {},
    alpha = 1,
    flash = 0,
    lineWidth = 0.05,
    phase = 0,
    eyes = 'dot',
    showScarf = false,
    showBand = false,
    swoosh = null,
    scaleY = 1,
  } = opts;

  if (alpha <= 0.01 || !pose) return;

  const body = colors.body || '#f2f7ff';
  const far = colors.far || '#93a9c9';
  const accent = colors.accent || '#41f6ff';
  const dark = colors.dark || '#0a1020';
  const eyeColor = colors.eye || accent;

  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.translate(x, y);
  ctx.scale(facing * scale, scale * scaleY);
  ctx.translate(0, -0.5);
  ctx.rotate(rot);
  ctx.translate(0, 0.5);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  const hip = { x: pose.hipX, y: -0.5 + pose.bob };
  const upDir = (a) => [Math.sin(a), -Math.cos(a)];
  const downDir = (a) => [Math.sin(a), Math.cos(a)];
  const add = (p, [dx, dy], len = 1) => [p[0] + dx * len, p[1] + dy * len];

  const t = pose.torso;
  const neck = add([hip.x, hip.y], upDir(t), 0.345);
  const shoulder = add([hip.x, hip.y], upDir(t), 0.272);
  const head = add(neck, upDir(t + pose.headTilt), 0.113);
  const headR = 0.099;

  const armFarShoulder = [shoulder[0] - 0.008, shoulder[1] + 0.004];
  const elbowFar = add(armFarShoulder, downDir(pose.armFar[0]), 0.185);
  const handFar = add(elbowFar, downDir(pose.armFar[0] + pose.armFar[1]), 0.18);

  const armNearShoulder = [shoulder[0] + 0.008, shoulder[1]];
  const elbowNear = add(armNearShoulder, downDir(pose.armNear[0]), 0.19);
  const handNear = add(elbowNear, downDir(pose.armNear[0] + pose.armNear[1]), 0.187);

  const hipFar = [hip.x - 0.018, hip.y + 0.01];
  const kneeFar = add(hipFar, downDir(pose.legFar[0]), 0.245);
  const footFar = add(kneeFar, downDir(pose.legFar[0] - pose.legFar[1]), 0.275);

  const hipNear = [hip.x + 0.018, hip.y - 0.005];
  const kneeNear = add(hipNear, downDir(pose.legNear[0]), 0.248);
  const footNear = add(kneeNear, downDir(pose.legNear[0] - pose.legNear[1]), 0.278);

  const torsoPath = [[hip.x, hip.y], neck];
  const farArmPath = [armFarShoulder, elbowFar, handFar];
  const nearArmPath = [armNearShoulder, elbowNear, handNear];
  const farLegPath = [hipFar, kneeFar, footFar];
  const nearLegPath = [hipNear, kneeNear, footNear];

  const stepPhase = phase;
  const wobble = Math.sin(stepPhase * 1.3) * 0.012;

  // ---- floor contact shadow handled by the renderer; here only the figure ----

  // Scarves / ribbons behind the body.
  if (showScarf || showBand) {
    const ribbonColor = accent;
    const base = showScarf
      ? [neck[0] - 0.015, neck[1] + 0.012]
      : [head[0] - 0.075, head[1] - 0.012];
    const len = showScarf ? 0.2 : 0.13;
    ctx.globalAlpha = alpha * 0.85;
    ctx.strokeStyle = ribbonColor;
    ctx.lineWidth = showScarf ? 0.038 : 0.024;
    ctx.beginPath();
    ctx.moveTo(base[0], base[1]);
    for (let i = 1; i <= 3; i++) {
      const px = base[0] - len * (i / 3) + Math.sin(stepPhase * 7 + i * 1.2) * 0.015;
      const py = base[1] + 0.02 + i * 0.016 + Math.sin(stepPhase * 6 + i) * 0.008;
      ctx.lineTo(px, py);
    }
    ctx.stroke();
    if (showBand) {
      ctx.lineWidth = 0.028;
      ctx.beginPath();
      ctx.moveTo(head[0] - headR * 0.92, head[1] - 0.008);
      ctx.lineTo(head[0] + headR * 0.55, head[1] - 0.02);
      ctx.stroke();
    }
  }

  // ---- glow underlay ----
  const glowAlpha = (0.18 + flash * 0.55) * alpha;
  if (glowAlpha > 0.01) {
    const glowColor = flash > 0.25 ? '#ffffff' : accent;
    const gw = lineWidth * 3.1;
    strokePath(ctx, torsoPath, gw, glowColor, glowAlpha * 0.75);
    strokePath(ctx, farArmPath, gw * 0.9, glowColor, glowAlpha * 0.5);
    strokePath(ctx, nearArmPath, gw, glowColor, glowAlpha * 0.75);
    strokePath(ctx, farLegPath, gw * 0.9, glowColor, glowAlpha * 0.5);
    strokePath(ctx, nearLegPath, gw, glowColor, glowAlpha * 0.75);
    ctx.globalAlpha = alpha * glowAlpha * 0.35;
    ctx.fillStyle = glowColor;
    ctx.beginPath();
    ctx.arc(head[0], head[1], headR * 1.55, 0, TAU);
    ctx.fill();
  }

  // ---- far side limbs ----
  strokePath(ctx, farLegPath, lineWidth * 0.92, far, alpha * 0.62);
  strokePath(ctx, farArmPath, lineWidth * 0.82, far, alpha * 0.62);

  // ---- torso ----
  strokePath(ctx, torsoPath, lineWidth, body, alpha);
  // chest notch for a little silhouette character
  strokePath(ctx, [[hip.x + 0.008, hip.y - 0.005], [shoulder[0], shoulder[1] - 0.01]], lineWidth * 0.55, body, alpha);

  // ---- head ----
  ctx.globalAlpha = alpha;
  ctx.beginPath();
  ctx.arc(head[0], head[1], headR, 0, TAU);
  ctx.fillStyle = dark;
  ctx.fill();
  ctx.strokeStyle = body;
  ctx.lineWidth = lineWidth * 0.9;
  ctx.stroke();

  // headband knot (drawn on top of head rim)
  if (showBand) {
    ctx.globalAlpha = alpha;
    ctx.strokeStyle = accent;
    ctx.lineWidth = 0.026;
    ctx.beginPath();
    ctx.arc(head[0], head[1], headR, Math.PI * 1.08, Math.PI * 1.86);
    ctx.stroke();
  }

  // eyes
  if (eyes === 'dot') {
    ctx.globalAlpha = alpha;
    ctx.fillStyle = eyeColor;
    ctx.beginPath();
    ctx.arc(head[0] + 0.038, head[1] - 0.004, 0.018, 0, TAU);
    ctx.fill();
    ctx.globalAlpha = alpha * 0.35;
    ctx.beginPath();
    ctx.arc(head[0] + 0.038, head[1] - 0.004, 0.036, 0, TAU);
    ctx.fill();
  } else if (eyes === 'slit') {
    ctx.globalAlpha = alpha;
    ctx.strokeStyle = eyeColor;
    ctx.lineWidth = 0.017;
    ctx.beginPath();
    ctx.moveTo(head[0] + 0.018, head[1] - 0.005);
    ctx.lineTo(head[0] + 0.065, head[1] - 0.012);
    ctx.stroke();
  }

  // ---- near side limbs ----
  strokePath(ctx, nearLegPath, lineWidth, body, alpha);
  strokePath(ctx, nearArmPath, lineWidth, body, alpha);

  // hands / feet caps add weight
  ctx.globalAlpha = alpha;
  ctx.fillStyle = body;
  for (const p of [handNear, handFar, footNear, footFar]) {
    ctx.beginPath();
    ctx.arc(p[0], p[1], lineWidth * 0.52, 0, TAU);
    ctx.fill();
  }

  // ---- attack swoosh ----
  if (swoosh && swoosh.t > 0 && swoosh.t < 1) {
    const tt = swoosh.t;
    const strength = Math.sin(clamp(tt, 0, 1) * Math.PI);
    if (swoosh.type === 'punch') {
      ctx.globalCompositeOperation = 'lighter';
      ctx.globalAlpha = alpha * strength * 0.5;
      ctx.strokeStyle = swoosh.color || accent;
      ctx.lineWidth = 0.028 + strength * 0.05;
      ctx.beginPath();
      ctx.arc(shoulder[0] + 0.05, shoulder[1], 0.4, -0.65, 0.55);
      ctx.stroke();
      ctx.globalAlpha = alpha * strength * 0.22;
      ctx.lineWidth = 0.12;
      ctx.beginPath();
      ctx.arc(shoulder[0] + 0.05, shoulder[1], 0.36, -0.55, 0.45);
      ctx.stroke();
      ctx.globalCompositeOperation = 'source-over';
    } else if (swoosh.type === 'kick') {
      ctx.globalCompositeOperation = 'lighter';
      ctx.globalAlpha = alpha * strength * 0.48;
      ctx.strokeStyle = swoosh.color || accent;
      ctx.lineWidth = 0.03 + strength * 0.06;
      ctx.beginPath();
      ctx.arc(hip.x, hip.y + 0.02, 0.55, -0.3, 0.9);
      ctx.stroke();
      ctx.globalAlpha = alpha * strength * 0.2;
      ctx.lineWidth = 0.15;
      ctx.beginPath();
      ctx.arc(hip.x, hip.y + 0.02, 0.48, -0.2, 0.8);
      ctx.stroke();
      ctx.globalCompositeOperation = 'source-over';
    }
  }

  ctx.restore();
}

export function drawGroundShadow(ctx, x, y, width, alpha = 0.32, squash = 1) {
  if (alpha <= 0.005) return;
  const r = width * 0.5;
  const gradient = ctx.createRadialGradient(x, y, 0, x, y, r);
  gradient.addColorStop(0, `rgba(0, 0, 0, ${alpha})`);
  gradient.addColorStop(0.55, `rgba(0, 0, 0, ${alpha * 0.55})`);
  gradient.addColorStop(1, 'rgba(0, 0, 0, 0)');
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(1, 0.26 * squash + 0.04);
  ctx.translate(-x, -y);
  ctx.fillStyle = gradient;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, TAU);
  ctx.fill();
  ctx.restore();
}

content.text:
Now fighters.js — big one. Let's define constants, attack data, Fighter class with player & AI.

Key physics:
- GRAVITY = 2100 world/s².
- Player jump velocity 760 → height ~137 units (jump). Good.
- Player speed 330, depth speed 260*? y units/s = 280/150? Since y is 0..1 and depth span 150 world units, depth speed in y units should be ~1.7/s to feel similar? Player moves 330 units/s in x. Depth screen speed = ySpeed * 150 px/s. Set ySpeed 1.4/s → 210 px/s. Good. Enemy ySpeed 0.9.
- Bounds x: [70, 2130], y: [0.06, 0.94].

Attack ranges in world units. Player height ~178. Range 112 plus target body width ~30. Enemy center distance <115. Good.

Hit detection also uses target's own x; distance forward. Attack origin at attacker x. To hit an enemy whose center is within range. Use forward distance from x to target x: dx = (target.x - x)*facing; require dx > -15 && dx < range && dz etc. With body widths maybe +20.

Enemy AI needs target x position offset. Let's implement.

Class data:

```js
export const PLAYER_ATTACKS = {
  punch1: {id:'punch1', startup:.055, active:.09, recover:.135, damage:6, range:118, depth:.34, knock:150, launch:0, stun:.20, heavy:false, meter:7, chain:'punch2', sound:'whoosh'},
  ...
}
```
Duration getter: attack.duration = startup+active+recover. Add computed.

punch3 launcher: launch 360, stun .45, heavy true, damage 13.
kick: damage 15, range 145, knock 420, stun .42, heavy true, recovery .3, meter 11.
airKick: damage 11, range 130, startup .07, active .18, recover .18, knock 260, launch 0.
special: handled separately.

Enemy defs by kind. Also give `enemy scale` etc.

Type configs:
```js
const ENEMY_TYPES = {
  grunt: {hp:34, speed:150, ySpeed:.9, height:176, line:.052, colors:{...}, score:100, blockChance:.14, attack:{...}, windupColor:'#ff6b5e'},
  ninja: {hp:26, speed:210, ... accent magenta, score:150, blockChance:.32, attack faster},
  brute: {hp:78, speed:112, height:200, line:.068, accent orange, score:250, blockChance:.28, armor:true, attack heavy},
  boss: {hp:240, speed:135, height:225, line:.08, accent red, score:1200, blockChance:.2, armor:'heavy', attack boss, name:'EL REY'},
}
```
Wait higher hp for boss 260.

Enemy colors: body should be tinted slightly:
- grunt: body '#e9eefc', far '#7c8fb0', accent '#ff5c6c', eye '#ff2f45', dark '#0a0f1c'.
- ninja: body '#cfd8ee', far '#5d6f92', accent '#ff4fd8', eye '#ff5ce1'.
- brute: body '#f0e6d8', far '#8f806e', accent '#ffa64d', eye '#ffb300'.
- boss: body '#f3e9ef', far '#8a6b7c', accent '#ff2f5e', eye '#ff1e46', with dark fill '#160711'. Boss should stand out: add red aura ring.

Player colors: body '#f4f9ff', far '#8ea6c6', accent '#41f6ff', eye '#bffcff', scarf yes.

Fighter class details:

```js
export class Fighter {
  constructor(game, opts) {
    this.game = game;
    this.kind = opts.kind;
    this.isPlayer = opts.isPlayer || false;
    this.x = opts.x; this.y = opts.y ?? 0.6; this.z = 0;
    this.mvx = 0; this.mvy = 0;
    this.vx = 0; this.vy = 0; this.vz = 0;
    this.facing = opts.facing ?? 1;
    this.height = opts.height ?? 178;
    this.maxHp = opts.hp; this.hp = opts.hp;
    this.speed = opts.speed; this.depthSpeed = opts.depthSpeed ?? 1.5;
    this.damageScale = 1;
    this.colors = opts.colors;
    this.lineWidth = opts.lineWidth ?? 0.052;
    this.showScarf = !!opts.showScarf;
    this.showBand = !!opts.showBand;
    this.eyes = opts.eyes ?? 'dot';
    this.attackDefs = opts.attacks || ENEMY_ATTACKS.grunt;
    this.blockChance = opts.blockChance || 0;
    this.armor = opts.armor || 0; // 0 none, 1 light-armor, 2 super armor
    this.scoreValue = opts.score || 0;
    this.isBoss = !!opts.isBoss;
    this.name = opts.name || '';
    this.state = 'idle';
    ...
    this.animPhase = rand(0,TAU);
    this.hitFlash = 0;
    this.alpha = 1;
    this.remove = false;
    this.hpVisible = 0; // timer showing health bar
    this.telegraph = 0;
    this.attackCooldown = rand(.6,1.5);
    this.aiTimer = rand(.2,.7);
    this.aiBias = rand(-.18,.18);
    this.blockTimer = 0;
    this.attackToken = false;
    this.hitThisAttack? 
    this.queued = null;
    this.comboWindow = 0;
    this.comboStep = 0;
    this.lastAttack = null;
    this.deadTimer=0;
    this.invuln=0;
    this.spawnFade=0;
    this.airAttackUsed=false;
    this.hitStop? no
  }
}
```

Update pipeline in game: `f.update(dt, input)` calls specific. Simpler: game calls player.updatePlayer(input,dt) and enemy.updateEnemy(dt). Both call `this.baseUpdate(dt)` then specific. Attacks handled in baseUpdate (advance attack timer, check end, and game resolves hits via separate method). Game collision resolution calls `f.getActiveAttack()`.

Let me write base:

```js
baseUpdate(dt) {
  this.animPhase += dt * (1 + Math.abs(this.mvx)/120);
  this.invuln = max(0, invuln-dt);
  this.hitFlash = max(0, hitFlash-dt);
  this.comboWindow = max(0, comboWindow-dt);
  if (comboWindow===0) comboStep=0? careful. Set when expires; if comboStep>0 and comboWindow==0 after decrement → comboStep=0.
  this.telegraph = max(0, telegraph-dt);
  this.hpVisible = max(0,hpVisible-dt);

  // physics
  this.x += (this.mvx + this.vx)*dt;
  this.y += (this.mvy + this.vy)*dt;
  this.vx = damp(this.vx, 0, 7, dt);
  this.vy = damp(this.vy, 0, 7, dt);
  this.mvx = damp(this.mvx,0, 18, dt) ... hmm movement should be direct, not damp each frame.
```
Better: movement computed in specific update directly, no mvx persistence. Use direct position change. Let `this.vx/vy` only for knockback. Then:
```
this.x += this.vx*dt; this.y += this.vy*dt; 
```
Movement in updatePlayer:
```
let ix = ...; 
this.x += ix*speed*dt; this.y += iy*depthSpeed*dt;
```
AI similar. Good. No acceleration needed; immediate movement feels responsive. Knockback added separately.

Gravity:
```
if (this.z>0 || this.vz>0) {
  this.vz -= GRAV*dt;
  this.z += this.vz*dt;
  if (this.z <= 0) { this.z=0; if (this.vz < -100) this.onLand(); this.vz=0; }
}
```
onLand: if state 'hurt' and this.wasLaunched → set state 'down', downTimer=0; spawn dust; sound.
If state 'jump' → idle.
If dead → stay dead.

State timers:
- attack: if state==='attack', advance attackTime. When attackTime >= duration → finishAttack.
- special separate: advance specialTime; every 0.16 → game.specialHit(this); rotation; end.
- dodge: timer; end → idle, rot=0.
- hurt: after hurtTimer → if state hurt and z<=0 → idle.
- down: after downTimer → getup with state 'getup' timer .25 invuln .5 then idle. Simplify: down 1.0s → state idle + invuln .5, and dust.
- block handled in update sets state.

Important: when attack state and z>0 (air attack), attack ends on landing? Air kick: ends when grounded or timer end. Use timer.

Face nearest enemy:
```
faceNearestEnemy(maxDist=420) {
  let best=null, bd=Infinity;
  for (const e of game.enemies) if (!e.dead && e.state!=='dead') { const dx=e.x-this.x; if (Math.abs(e.y-this.y)<.5) { const d=Math.abs(dx); if (d<bd) {bd=d;best=e} } }
  if (best && bd < maxDist) { this.facing = best.x < this.x ? -1 : 1; return best;}
  return null;
}
```
During attack, lock facing at start: `faceTarget(140)`.

Input axis: `const ix = (input.isDown('right')?1:0) - (input.isDown('left')?1:0)`, iy similar. Also keyboard only; joystick works via isDown threshold.

Player update:
```
updatePlayer(input, dt, game) {
  if (this.state==='dead') { this.deadUpdate(dt); return; }
  this.baseUpdate(dt);
  if (game.state !== 'playing') { this.animate(dt); return; }
  // actions
  const canAct = ['idle','walk','block'].includes(this.state) && this.z===0
  ...
}
