input.content:
import { TAU, makeRng, rand, clamp, lerp } from './utils.js';

function buildCityTile(opts) {
  const {
    seed = 1,
    width = 2048,
    height = 620,
    body = '#0c1326',
    edge = 'rgba(120, 170, 255, 0.09)',
    windowColors = ['#27406d'],
    windowChance = 0.35,
    minW = 70,
    maxW = 165,
    minH = 230,
    maxH = 540,
    windowW = 9,
    windowH = 12,
    gapX = 14,
    gapY = 20,
  } = opts;
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const g = canvas.getContext('2d');
  const rng = makeRng(seed);
  const r = (a, b) => a + rng() * (b - a);

  let x = -20;
  while (x < width) {
    const w = r(minW, maxW);
    const h = r(minH, maxH);
    const y = height - h;
    // main body
    g.fillStyle = body;
    g.fillRect(x, y, w, h);

    // subtle vertical shading
    const grad = g.createLinearGradient(x, 0, x + w, 0);
    grad.addColorStop(0, 'rgba(255,255,255,0.022)');
    grad.addColorStop(0.45, 'rgba(255,255,255,0)');
    grad.addColorStop(1, 'rgba(0,0,0,0.14)');
    g.fillStyle = grad;
    g.fillRect(x, y, w, h);

    g.fillStyle = edge;
    g.fillRect(x, y, 1, h);
    g.fillRect(x + w - 1, y, 1, h);

    // roof line
    g.fillStyle = 'rgba(255,255,255,0.05)';
    g.fillRect(x, y, w, 1.5);

    // roof furniture
    if (rng() < 0.55) {
      const rw = r(8, 26);
      g.fillStyle = body;
      g.fillRect(x + r(6, Math.max(8, w - rw - 6)), y - r(4, 16), rw, r(4, 16));
    }
    if (rng() < 0.34) {
      const ax = x + r(10, Math.max(14, w - 14));
      g.strokeStyle = 'rgba(160, 190, 255, 0.16)';
      g.lineWidth = 1;
      g.beginPath();
      g.moveTo(ax, y);
      g.lineTo(ax, y - r(18, 52));
      g.stroke();
      if (rng() < 0.6) {
        g.fillStyle = '#ff4d6a';
        g.globalAlpha = 0.7;
        g.beginPath();
        g.arc(ax, y - r(18, 40), 1.3, 0, TAU);
        g.fill();
        g.globalAlpha = 1;
      }
    }

    // windows grid
    const cols = Math.max(1, Math.floor((w - 16) / (windowW + 8)));
    const rows = Math.max(2, Math.floor((h - 24) / (windowH + gapY)));
    const cellW = (w - 16) / cols;
    const startY = y + 16;
    for (let cy = 0; cy < rows; cy++) {
      for (let cx = 0; cx < cols; cx++) {
        const on = rng() < windowChance;
        if (!on) continue;
        const wx = x + 9 + cx * cellW;
        const wy = startY + cy * (windowH + gapY);
        const color = windowColors[Math.floor(rng() * windowColors.length)];
        g.globalAlpha = r(0.35, 1);
        g.fillStyle = color;
        g.fillRect(wx, wy, windowW * 0.7, windowH * 0.5);
        if (rng() < 0.18) {
          g.globalAlpha = 0.1;
          g.fillRect(wx - 3, wy - 3, windowW * 0.7 + 6, windowH * 0.5 + 6);
        }
      }
    }
    g.globalAlpha = 1;

    // ground-floor glow for the nearest layer
    if (opts.streetGlow) {
      const sg = g.createLinearGradient(0, height - 50, 0, height);
      sg.addColorStop(0, 'rgba(255, 120, 190, 0)');
      sg.addColorStop(1, opts.streetGlow);
      g.fillStyle = sg;
      g.fillRect(x, height - 50, w, 50);
    }

    x += w + r(2, gapX);
  }
  return canvas;
}

const SIGNS = [
  { x: 260, y: 238, w: 58, h: 142, text: 'HOTEL', color: '#ff3d9a', vertical: true, speed: 1.7 },
  { x: 690, y: 128, w: 122, h: 42, text: 'RAMEN', color: '#41f6ff', vertical: false, speed: 2.6 },
  { x: 1210, y: 262, w: 64, h: 168, text: 'BAR', color: '#ff9d4d', vertical: true, speed: 2.1 },
  { x: 1660, y: 154, w: 96, h: 40, text: '24H', color: '#b8ff63', vertical: false, speed: 1.4 },
  { x: 1960, y: 246, w: 54, h: 130, text: 'INN', color: '#8b7dff', vertical: true, speed: 2.9 },
];

const LAMPS = [
  { x: 340, side: 1 },
  { x: 1640, side: -1 },
];

const BARRELS = [
  { x: 130, seed: 11 },
  { x: 2080, seed: 29 },
];

const PUDDLES = [
  { x: 480, y: 0.3, w: 150, h: 26, color: 'rgba(65, 246, 255, 0.22)' },
  { x: 910, y: 0.72, w: 210, h: 34, color: 'rgba(255, 61, 154, 0.2)' },
  { x: 1420, y: 0.22, w: 130, h: 22, color: 'rgba(255, 157, 77, 0.18)' },
  { x: 1840, y: 0.68, w: 180, h: 30, color: 'rgba(139, 125, 255, 0.2)' },
  { x: 220, y: 0.86, w: 110, h: 20, color: 'rgba(65, 246, 255, 0.16)' },
];

export class World {
  constructor() {
    this.time = 0;
    this.far = buildCityTile({
      seed: 7, height: 560,
      body: '#0a1020',
      edge: 'rgba(110, 160, 255, 0.05)',
      windowColors: ['#1b2b4c', '#243b63', '#3a5c8e', '#79d8ff'],
      windowChance: 0.17, minW: 60, maxW: 150, minH: 170, maxH: 460,
      windowW: 7, windowH: 9, gapX: 22, gapY: 22,
    });
    this.mid = buildCityTile({
      seed: 23, height: 620,
      body: '#0d152a',
      edge: 'rgba(140, 190, 255, 0.09)',
      windowColors: ['#ffbe7a', '#ff6ea6', '#63e9ff', '#3c5c92', '#ffd9a0'],
      windowChance: 0.28, minW: 80, maxW: 180, minH: 210, maxH: 520,
      windowW: 10, windowH: 13, gapX: 12, gapY: 18,
      streetGlow: 'rgba(255, 90, 160, 0.05)',
    });
    this.fencePattern = this.makeFencePattern();
    this.rain = [];
    for (let i = 0; i < 150; i++) {
      this.rain.push({
        x: Math.random(), y: Math.random(),
        len: rand(7, 22), speed: rand(0.55, 1.35), alpha: rand(0.05, 0.18),
      });
    }
    this.splashes = [];
    this.splashTimer = 0;
    this.stars = [];
    const rng = makeRng(91);
    for (let i = 0; i < 90; i++) {
      this.stars.push({
        x: rng(), y: rng() * 0.55, r: 0.5 + rng() * 1.4,
        a: 0.2 + rng() * 0.7, speed: 0.4 + rng() * 1.8, phase: rng() * TAU,
      });
    }
    this.fog = [
      { x: 0.15, y: 0.55, r: 0.4, speed: 0.012 },
      { x: 0.72, y: 0.62, r: 0.32, speed: 0.017 },
    ];
  }

  makeFencePattern() {
    const c = document.createElement('canvas');
    c.width = 24;
    c.height = 24;
    const g = c.getContext('2d');
    g.strokeStyle = 'rgba(150, 185, 235, 0.17)';
    g.lineWidth = 1;
    g.beginPath();
    g.moveTo(0, 0); g.lineTo(24, 24);
    g.moveTo(24, 0); g.lineTo(0, 24);
    g.stroke();
    g.globalAlpha = 0.5;
    g.beginPath();
    g.moveTo(0, 12); g.lineTo(24, 12);
    g.stroke();
    return c;
  }

  update(dt) {
    this.time += dt;
    this.splashTimer -= dt;
  }

  drawSky(ctx, view) {
    const { W, H, s, camX } = view;
    const sky = ctx.createLinearGradient(0, 0, 0, H);
    sky.addColorStop(0, '#04050d');
    sky.addColorStop(0.34, '#0a0e22');
    sky.addColorStop(0.62, '#161a3d');
    sky.addColorStop(0.82, '#2a1f45');
    sky.addColorStop(1, '#0b0d1c');
    ctx.fillStyle = sky;
    ctx.fillRect(0, 0, W, H);

    // horizon neon haze
    const hazeY = view.baseline - view.depthPx * 0.5 - 50 * s;
    const haze = ctx.createRadialGradient(W * 0.6, hazeY, 0, W * 0.6, hazeY, Math.max(W * 0.6, 420));
    haze.addColorStop(0, 'rgba(255, 61, 154, 0.16)');
    haze.addColorStop(0.45, 'rgba(120, 70, 200, 0.1)');
    haze.addColorStop(1, 'rgba(20, 20, 50, 0)');
    ctx.fillStyle = haze;
    ctx.fillRect(0, 0, W, H);

    // moon
    const mx = W * 0.76 - camX * 0.015 * s;
    const my = H * 0.18;
    const mr = Math.max(26, 56 * s);
    const moonGlow = ctx.createRadialGradient(mx, my, mr * 0.4, mx, my, mr * 4.6);
    moonGlow.addColorStop(0, 'rgba(255, 238, 210, 0.25)');
    moonGlow.addColorStop(0.35, 'rgba(255, 170, 190, 0.1)');
    moonGlow.addColorStop(1, 'rgba(255, 120, 180, 0)');
    ctx.fillStyle = moonGlow;
    ctx.fillRect(mx - mr * 5, my - mr * 5, mr * 10, mr * 10);

    ctx.save();
    ctx.beginPath();
    ctx.arc(mx, my, mr, 0, TAU);
    ctx.clip();
    const moonBody = ctx.createLinearGradient(mx, my - mr, mx, my + mr);
    moonBody.addColorStop(0, '#fff6e2');
    moonBody.addColorStop(0.55, '#ffe0c8');
    moonBody.addColorStop(1, '#ffb6b0');
    ctx.fillStyle = moonBody;
    ctx.fillRect(mx - mr, my - mr, mr * 2, mr * 2);
    ctx.fillStyle = 'rgba(150, 110, 140, 0.22)';
    ctx.beginPath(); ctx.arc(mx - mr * 0.32, my - mr * 0.2, mr * 0.22, 0, TAU); ctx.fill();
    ctx.beginPath(); ctx.arc(mx + mr * 0.3, my + mr * 0.28, mr * 0.16, 0, TAU); ctx.fill();
    ctx.beginPath(); ctx.arc(mx + mr * 0.12, my - mr * 0.42, mr * 0.1, 0, TAU); ctx.fill();
    ctx.restore();

    // stars
    for (const star of this.stars) {
      const a = star.a * (0.55 + 0.45 * Math.sin(this.time * star.speed + star.phase));
      ctx.globalAlpha = a * 0.8;
      ctx.fillStyle = '#d9e6ff';
      ctx.beginPath();
      ctx.arc(star.x * W, star.y * H, star.r * Math.max(0.7, s), 0, TAU);
      ctx.fill();
    }
    ctx.globalAlpha = 1;

    // thin clouds
    ctx.save();
    ctx.globalAlpha = 0.06;
    for (let i = 0; i < 4; i++) {
      const cy = H * (0.16 + i * 0.07);
      const cx = ((this.time * (6 + i * 3) + i * 420) % (W + 600)) - 300;
      const cw = 380 + i * 90;
      const ch = 22 + i * 18;
      const cg = ctx.createLinearGradient(cx, cy, cx + cw, cy);
      cg.addColorStop(0, 'rgba(190, 190, 255, 0)');
      cg.addColorStop(0.5, 'rgba(190, 190, 255, 0.7)');
      cg.addColorStop(1, 'rgba(190, 190, 255, 0)');
      ctx.fillStyle = cg;
      ctx.beginPath();
      ctx.ellipse(cx + cw / 2, cy, cw / 2, ch, 0, 0, TAU);
      ctx.fill();
    }
    ctx.restore();

    // distant glow behind the city
    const cityGlow = ctx.createRadialGradient(W * 0.35, view.baseline - 40 * s, 10, W * 0.35, view.baseline - 40 * s, W * 0.55);
    cityGlow.addColorStop(0, 'rgba(255, 100, 180, 0.12)');
    cityGlow.addColorStop(0.5, 'rgba(90, 120, 220, 0.06)');
    cityGlow.addColorStop(1, 'rgba(20, 20, 40, 0)');
    ctx.fillStyle = cityGlow;
    ctx.fillRect(0, 0, W, H);
  }

  drawTile(ctx, tile, view, parallax, bottom, alpha = 1, warm = false) {
    const { W, s, camX } = view;
    const tw = tile.width * s;
    const th = tile.height * s;
    const shift = ((camX * parallax * s) % tw + tw) % tw;
    ctx.save();
    ctx.globalAlpha = alpha;
    if (warm) ctx.filter = 'none';
    for (let x = -shift - tw; x < W + tw; x += tw) {
      ctx.drawImage(tile, x, bottom - th, tw, th);
    }
    ctx.restore();
  }

  drawCity(ctx, view) {
    const { s, baseline, depthPx } = view;
    const horizon = baseline - depthPx * 0.5 - 26 * s;
    this.drawTile(ctx, this.far, view, 0.08, horizon + 6 * s, 0.92);
    this.drawTile(ctx, this.mid, view, 0.3, horizon + 16 * s, 1);

    // animated neon signs
    for (const sign of SIGNS) {
      const sx = (sign.x - view.camX * 0.42) * s + view.W / 2;
      const sy = horizon - sign.y * s;
      if (sx < -260 * s || sx > view.W + 260 * s) continue;
      const flicker = 0.72 + 0.28 * Math.sin(this.time * sign.speed + sign.x);
      const on = Math.sin(this.time * sign.speed * 2.7 + sign.x) > -0.86;
      const alpha = on ? flicker : 0.16;
      ctx.save();
      ctx.globalAlpha = alpha;
      const w = sign.w * s;
      const h = sign.h * s;
      // board
      ctx.fillStyle = 'rgba(8, 9, 20, 0.92)';
      ctx.fillRect(sx - w / 2, sy - h / 2, w, h);
      ctx.strokeStyle = sign.color;
      ctx.lineWidth = Math.max(1, 1.6 * s);
      ctx.globalAlpha = alpha * 0.75;
      ctx.strokeRect(sx - w / 2, sy - h / 2, w, h);
      // glow
      ctx.globalAlpha = alpha * 0.22;
      ctx.shadowColor = sign.color;
      ctx.shadowBlur = 22 * s;
      ctx.fillStyle = sign.color;
      ctx.fillRect(sx - w / 2 + 3 * s, sy - h / 2 + 3 * s, w - 6 * s, h - 6 * s);
      ctx.shadowBlur = 0;
      // text
      ctx.globalAlpha = alpha;
      ctx.fillStyle = '#fff7fb';
      ctx.shadowColor = sign.color;
      ctx.shadowBlur = 14 * s;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      if (sign.vertical) {
        const fontSize = Math.min(w * 0.44, h / (sign.text.length + 1.6));
        ctx.font = `800 ${fontSize}px ui-monospace, Menlo, monospace`;
        const step = h / (sign.text.length + 0.6);
        for (let i = 0; i < sign.text.length; i++) {
          ctx.fillText(sign.text[i], sx, sy - h / 2 + step * (i + 0.8));
        }
      } else {
        const fontSize = Math.min(h * 0.58, w / (sign.text.length * 0.82));
        ctx.font = `800 ${fontSize}px ui-monospace, Menlo, monospace`;
        ctx.fillText(sign.text, sx, sy + 1 * s);
      }
      ctx.restore();
    }
  }

  drawGround(ctx, view) {
    const { W, H, s, baseline, depthPx, camX } = view;
    const horizon = baseline - depthPx * 0.5 - 26 * s;
    const backWalk = baseline - depthPx * 0.5;

    // asphalt slab
    const ground = ctx.createLinearGradient(0, horizon, 0, H);
    ground.addColorStop(0, '#151b31');
    ground.addColorStop(0.18, '#101728');
    ground.addColorStop(0.62, '#090e1b');
    ground.addColorStop(1, '#050810');
    ctx.fillStyle = ground;
    ctx.fillRect(0, horizon, W, H - horizon);

    // wet sheen bands
    for (let i = 0; i < 4; i++) {
      const y = horizon + (depthPx + 60 * s) * (i / 3);
      ctx.globalAlpha = 0.06;
      ctx.fillStyle = i % 2 === 0 ? '#7f9cff' : '#ff6aa8';
      ctx.fillRect(0, y, W, 1.5 * s);
    }
    ctx.globalAlpha = 1;

    // sidewalk / curb at the back
    ctx.fillStyle = '#0b0f1d';
    ctx.fillRect(0, horizon - 26 * s, W, 30 * s);
    ctx.fillStyle = 'rgba(160, 190, 255, 0.16)';
    ctx.fillRect(0, horizon + 2 * s, W, Math.max(1, 2 * s));
    ctx.fillStyle = 'rgba(0, 0, 0, 0.45)';
    ctx.fillRect(0, horizon + 4 * s, W, 7 * s);

    // fence
    ctx.save();
    const fenceTop = horizon - 104 * s;
    const fenceH = 78 * s;
    const pattern = ctx.createPattern(this.fencePattern, 'repeat');
    if (pattern) {
      ctx.fillStyle = pattern;
      ctx.globalAlpha = 0.5;
      ctx.fillRect(0, fenceTop, W, fenceH);
    }
    ctx.globalAlpha = 0.5;
    ctx.strokeStyle = 'rgba(170, 200, 255, 0.16)';
    ctx.lineWidth = Math.max(1, 2.2 * s);
    ctx.beginPath();
    ctx.moveTo(0, fenceTop);
    ctx.lineTo(W, fenceTop);
    ctx.stroke();
    for (let wx = 60; wx < 2260; wx += 190) {
      const sx = (wx - camX) * s + W / 2;
      if (sx < -20 || sx > W + 20) continue;
      ctx.globalAlpha = 0.55;
      ctx.fillStyle = 'rgba(10, 13, 25, 0.9)';
      ctx.fillRect(sx - 2.4 * s, fenceTop, 4.8 * s, fenceH + 16 * s);
      ctx.fillStyle = 'rgba(160, 190, 255, 0.18)';
      ctx.fillRect(sx - 2.4 * s, fenceTop, Math.max(1, 1.2 * s), fenceH + 16 * s);
    }
    ctx.restore();

    // depth guide lines
    ctx.save();
    ctx.globalAlpha = 0.09;
    ctx.strokeStyle = '#8bb0ff';
    ctx.lineWidth = 1;
    for (let i = 0; i < 3; i++) {
      const y = baseline + depthPx * (i / 3 - 0.5) + 26 * s;
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(W, y);
      ctx.stroke();
    }
    ctx.restore();

    // puddles and neon reflections
    for (const p of PUDDLES) {
      const sx = (p.x - camX) * s + W / 2;
      const sy = baseline + (p.y - 0.5) * depthPx;
      if (sx < -p.w * s || sx > W + p.w * s) continue;
      ctx.save();
      ctx.translate(sx, sy);
      ctx.scale(1, 0.18);
      const pg = ctx.createRadialGradient(0, 0, 0, 0, 0, (p.w / 2) * s);
      pg.addColorStop(0, p.color);
      pg.addColorStop(0.6, p.color.replace(/[\d.]+\)$/, '0.08)'));
      pg.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = pg;
      ctx.beginPath();
      ctx.arc(0, 0, (p.w / 2) * s, 0, TAU);
      ctx.fill();
      ctx.globalAlpha = 0.35;
      ctx.strokeStyle = 'rgba(200, 230, 255, 0.3)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.arc(0, 0, (p.w / 2) * s * 0.62, 0.2, Math.PI - 0.4);
      ctx.stroke();
      ctx.restore();
    }

    // manholes
    for (const m of [{ x: 720, y: 0.6 }, { x: 1510, y: 0.38 }]) {
      const sx = (m.x - camX) * s + W / 2;
      const sy = baseline + (m.y - 0.5) * depthPx;
      if (sx < -60 || sx > W + 60) continue;
      ctx.save();
      ctx.globalAlpha = 0.55;
      ctx.fillStyle = '#0a0e19';
      ctx.beginPath();
      ctx.ellipse(sx, sy, 28 * s, 8 * s, 0, 0, TAU);
      ctx.fill();
      ctx.strokeStyle = 'rgba(130, 160, 210, 0.2)';
      ctx.lineWidth = 1;
      irc: for (let i = 0; i < 3; i++) {
        ctx.beginPath();
        ctx.ellipse(sx, sy, (12 + i * 6) * s, (3.4 + i * 1.8) * s, 0, 0, TAU);
        ctx.stroke();
      }
      ctx.restore();
    }

    // neon reflection streaks on the wet street
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (const sign of SIGNS) {
      const sx = (sign.x - camX * 0.42) * s + W / 2;
      if (sx < -200 || sx > W + 200) continue;
      const rg = ctx.createLinearGradient(0, horizon, 0, H * 0.96);
      rg.addColorStop(0, this.hexA(sign.color, 0.13));
      rg.addColorStop(0.4, this.hexA(sign.color, 0.05));
      rg.addColorStop(1, this.hexA(sign.color, 0));
      ctx.fillStyle = rg;
      const w = (sign.w * 0.5) * s;
      ctx.fillRect(sx - w / 2, horizon, w, H * 0.96 - horizon);
    }
    ctx.restore();

    // pavement cracks
    ctx.save();
    ctx.globalAlpha = 0.18;
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 1;
    const rng = makeRng(41);
    for (let i = 0; i < 9; i++) {
      const x = rng() * W;
      const y = horizon + 40 * s + rng() * (H - horizon);
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x + (rng() - 0.5) * 50 * s, y + (rng() - 0.5) * 8 * s);
      ctx.lineTo(x + (rng() - 0.5) * 90 * s, y + (rng() - 0.5) * 12 * s);
      ctx.stroke();
    }
    ctx.restore();

    // front-of-stage darkening
    const front = ctx.createLinearGradient(0, H * 0.72, 0, H);
    front.addColorStop(0, 'rgba(2, 4, 10, 0)');
    front.addColorStop(1, 'rgba(2, 4, 10, 0.72)');
    ctx.fillStyle = front;
    ctx.fillRect(0, H * 0.72, W, H * 0.28);

    this.drawProps(ctx, view, horizon, backWalk);
  }

  hexA(hex, alpha) {
    const h = hex.replace('#', '');
    const r = parseInt(h.slice(0, 2), 16);
    const g = parseInt(h.slice(2, 4), 16);
    const b = parseInt(h.slice(4, 6), 16);
    return `rgba(${r}, ${g}, ${b}, ${alpha})`;
  }

  drawProps(ctx, view, horizon, backWalk) {
    const { W, s, baseline, depthPx, camX } = view;

    // street lamps
    for (const lamp of LAMPS) {
      const sx = (lamp.x - camX) * s + W / 2;
      if (sx < -160 * s || sx > W + 160 * s) continue;
      const baseY = horizon + 10 * s;
      const topY = horizon - 230 * s;
      const armX = sx + lamp.side * 46 * s;
      ctx.save();
      // pole
      ctx.strokeStyle = '#141b2d';
      ctx.lineWidth = 5 * s;
      ctx.beginPath();
      ctx.moveTo(sx, baseY);
      ctx.lineTo(sx, topY);
      ctx.quadraticCurveTo(sx, topY - 26 * s, armX, topY - 30 * s);
      ctx.stroke();
      ctx.strokeStyle = 'rgba(150, 190, 255, 0.14)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(sx + 2 * s, baseY);
      ctx.lineTo(sx + 2 * s, topY);
      ctx.stroke();
      // lamp head
      ctx.fillStyle = '#1a2236';
      ctx.beginPath();
      ctx.ellipse(armX, topY - 30 * s, 12 * s, 6 * s, 0, 0, TAU);
      ctx.fill();
      // light
      const lx = armX;
      const ly = topY - 24 * s;
      const glow = ctx.createRadialGradient(lx, ly, 0, lx, ly, 110 * s);
      glow.addColorStop(0, 'rgba(190, 235, 255, 0.5)');
      glow.addColorStop(0.25, 'rgba(120, 200, 255, 0.16)');
      glow.addColorStop(1, 'rgba(100, 180, 255, 0)');
      ctx.fillStyle = glow;
      ctx.beginPath();
      ctx.arc(lx, ly, 110 * s, 0, TAU);
      ctx.fill();
      // light cone
      const cone = ctx.createLinearGradient(lx, ly, lx, baseY);
      cone.addColorStop(0, 'rgba(160, 220, 255, 0.09)');
      cone.addColorStop(1, 'rgba(160, 220, 255, 0)');
      ctx.fillStyle = cone;
      ctx.beginPath();
      ctx.moveTo(lx - 10 * s, ly);
      ctx.lineTo(lx + 10 * s, ly);
      ctx.lineTo(lx + 120 * s, baseY + 20 * s);
      ctx.lineTo(lx - 120 * s, baseY + 20 * s);
      ctx.closePath();
      ctx.fill();
      ctx.fillStyle = '#e8f8ff';
      ctx.beginPath();
      ctx.ellipse(lx, ly, 6 * s, 3 * s, 0, 0, TAU);
      ctx.fill();
      ctx.restore();
    }

    // burning barrels
    for (const barrel of BARRELS) {
      const sx = (barrel.x - camX) * s + W / 2;
      if (sx < -100 * s || sx > W + 100 * s) continue;
      const by = horizon + 18 * s;
      const bw = 20 * s;
      const bh = 26 * s;
      ctx.save();
      ctx.fillStyle = '#1a1a24';
      ctx.beginPath();
      ctx.ellipse(sx, by, bw, bh * 0.45, 0, 0, TAU);
      ctx.fill();
      ctx.fillStyle = '#231a1c';
      ctx.fillRect(sx - bw, by - bh, bw * 2, bh);
      ctx.strokeStyle = 'rgba(255, 140, 70, 0.28)';
      ctx.lineWidth = 1.5 * s;
      ctx.beginPath();
      ctx.moveTo(sx - bw, by - bh * 0.7);
      ctx.lineTo(sx + bw, by - bh * 0.7);
      ctx.moveTo(sx - bw, by - bh * 0.25);
      ctx.lineTo(sx + bw, by - bh * 0.25);
      ctx.stroke();
      ctx.fillStyle = '#0e0c12';
      ctx.beginPath();
      ctx.ellipse(sx, by - bh, bw, bh * 0.4, 0, 0, TAU);
      ctx.fill();
      // flame glow
      const fg = ctx.createRadialGradient(sx, by - bh - 6 * s, 0, sx, by - bh - 6 * s, 60 * s);
      fg.addColorStop(0, 'rgba(255, 160, 60, 0.5)');
      fg.addColorStop(0.4, 'rgba(255, 90, 30, 0.16)');
      fg.addColorStop(1, 'rgba(255, 60, 20, 0)');
      ctx.fillStyle = fg;
      ctx.beginPath();
      ctx.arc(sx, by - bh - 6 * s, 60 * s, 0, TAU);
      ctx.fill();
      // flames
      ctx.globalCompositeOperation = 'lighter';
      for (let i = 0; i < 4; i++) {
        const ph = this.time * (5 + i) + barrel.seed + i * 2;
        const fh = (10 + Math.sin(ph) * 4 + i * 3) * s;
        const fx = sx + Math.sin(ph * 0.7) * 5 * s;
        ctx.globalAlpha = 0.55 - i * 0.1;
        ctx.fillStyle = i < 2 ? '#ffcf6a' : '#ff7a3c';
        ctx.beginPath();
        ctx.ellipse(fx, by - bh - fh * 0.55, (6 - i) * s, fh, 0, 0, TAU);
        ctx.fill();
      }
      ctx.globalAlpha = 0.2;
      ctx.fillStyle = '#ff9d4d';
      for (let i = 0; i < 3; i++) {
        const ph = this.time * 0.9 + i * 2 + barrel.seed;
        ctx.beginPath();
        ctx.arc(sx + Math.sin(ph) * 24 * s, by - bh - (20 + Math.sin(ph * 1.7) * 10) * s, 1.6 * s, 0, TAU);
        ctx.fill();
      }
      ctx.restore();
    }

    // steam vents
    for (const vent of [{ x: 1010 }, { x: 1900 }]) {
      const sx = (vent.x - camX) * s + W / 2;
      if (sx < -120 || sx > W + 120) continue;
      const sy = baseline + depthPx * 0.25;
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      for (let i = 0; i < 4; i++) {
        const ph = (this.time * 0.22 + i * 0.25) % 1;
        const alpha = (1 - ph) * 0.07;
        const radius = (14 + ph * 52) * s;
        const gy = sy - ph * 150 * s;
        const grad = ctx.createRadialGradient(sx + Math.sin(ph * 6 + i) * 18 * s, gy, 0, sx, gy, radius);
        grad.addColorStop(0, `rgba(170, 200, 255, ${alpha})`);
        grad.addColorStop(1, 'rgba(170, 200, 255, 0)');
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.arc(sx, gy, radius, 0, TAU);
        ctx.fill();
      }
      ctx.restore();
    }
  }

  drawRain(ctx, view, dt) {
    const { W, H, s } = view;
    ctx.save();
    ctx.strokeStyle = 'rgba(170, 210, 255, 1)';
    ctx.lineWidth = 1;
    for (const drop of this.rain) {
      drop.x += (0.05 * drop.speed * dt) / Math.max(0.4, W / 1200);
      drop.y += drop.speed * dt * 0.42;
      if (drop.y > 1.02) {
        drop.y = -0.04;
        drop.x = Math.random();
      }
      if (drop.x > 1.02) drop.x -= 1.04;
      const x = drop.x * W;
      const y = drop.y * H;
      const len = drop.len * Math.max(0.7, s);
      ctx.globalAlpha = drop.alpha;
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x + len * 0.22, y + len);
      ctx.stroke();
    }
    ctx.globalAlpha = 1;
    ctx.restore();
  }

  drawAtmosphere(ctx, view) {
    const { W, H, baseline, depthPx } = view;
    // ground fog
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (const f of this.fog) {
      const x = ((f.x + Math.sin(this.time * f.speed * 6) * 0.02) * W);
      const y = baseline + (f.y - 0.5) * depthPx;
      const r = f.r * W;
      const grad = ctx.createRadialGradient(x, y, 0, x, y, r);
      grad.addColorStop(0, 'rgba(120, 160, 240, 0.045)');
      grad.addColorStop(1, 'rgba(120, 160, 240, 0)');
      ctx.fillStyle = grad;
      ctx.fillRect(0, 0, W, H);
    }
    ctx.restore();
  }
}

