let last = performance.now();
let lastRenderAt = 0;
let lastRenderState = '';
let crashed = false;

function frame(now) {
  const dt = Math.min(0.05, Math.max(0, (now - last) / 1000));
  last = now;

  input.pollGamepad();

  if (input.pressed('mute')) {
    const muted = audio.toggleMute();
    ui.setMuted(muted);
  }
  if (input.pressed('pause')) {
    if (game.state === 'playing' || game.state === 'paused') game.togglePause();
  }
  if (input.pressed('start')) {
    if (game.state === 'menu') game.startGame();
    else if (game.state === 'gameover') game.restart();
    else if (game.state === 'victory') game.restart();
  }

  game.update(dt);

  // Outside live combat the scene is mostly static. Rendering it at ~9 fps
  // keeps software-rendered browsers responsive (and overlay buttons easy to
  // click) without changing the look of the frozen scene.
  const calm = game.state !== 'playing' && game.state !== 'dying';
  if (!calm || now - lastRenderAt > 110 || game.state !== lastRenderState) {
    game.render();
    lastRenderAt = now;
    lastRenderState = game.state;
  }

  audio.updateMusic();
  input.endFrame();

  if (!crashed) requestAnimationFrame(frame);
}

