import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch(config.browser.launchOptions);
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.addInitScript(() => {
  window.__long = [];
  new PerformanceObserver(list => {
    for (const e of list.getEntries()) window.__long.push([Math.round(e.startTime), Math.round(e.duration), e.name]);
  }).observe({ entryTypes: ['longtask'] });
  window.__ticks = [];
  const start = performance.now();
  function tick() {
    window.__ticks.push(Math.round(performance.now() - start));
    if (performance.now() - start < 5000) setTimeout(tick, 100);
  }
  setTimeout(tick, 100);
  const orig = HTMLCanvasElement.prototype.getContext;
  HTMLCanvasElement.prototype.getContext = function (...args) {
    const ctx = orig.apply(this, args);
    if (args[0] === '2d' && !ctx.__wrapped) {
      ctx.__wrapped = true;
      for (const name of ['fillRect', 'drawImage', 'createLinearGradient', 'createRadialGradient', 'fill', 'stroke']) {
        const fn = ctx[name];
        if (typeof fn !== 'function') continue;
        ctx[name] = function (...a) {
          const t = performance.now();
          const r = fn.apply(this, a);
          const d = performance.now() - t;
          if (d > 10) (window.__slow = window.__slow || []).push([name, Math.round(d), Math.round(t)]);
          return r;
        };
      }
    }
    return ctx;
  };
});
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.waitForFunction(() => document.fonts.status === 'loaded');
await page.waitForTimeout(3500);
const data = await page.evaluate(() => ({ long: window.__long, ticks: window.__ticks, slow: (window.__slow || []).slice(0, 30), nav: Math.round(performance.now()) }));
console.log(JSON.stringify(data, null, 1));
await browser.close();

