import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { startForCapture } from '/home/runner/work/_temp/omgithub-runtime/scripts/capture-start.mjs';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch(config.browser.launchOptions);
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.addInitScript(() => {
  window.__rects = [];
  const start = performance.now();
  function tick() {
    const b = document.getElementById('startBtn');
    if (b) {
      const r = b.getBoundingClientRect();
      const cs = getComputedStyle(b);
      const el = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
      window.__rects.push([Math.round(performance.now() - start), +r.x.toFixed(1), +r.y.toFixed(1), +r.width.toFixed(1), +r.height.toFixed(1), cs.opacity, cs.transform, el ? el.id || el.className : null]);
    }
    if (performance.now() - start < 6000) requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);
});
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.waitForFunction(() => document.fonts.status === 'loaded');
const t = Date.now();
let res;
try { res = await startForCapture(page, { enabled: true, selector: '', timeout: 4000 }); }
catch (e) { res = { clicked: false, reason: 'throw', msg: e.message.split('\n')[0] }; }
console.log('result', JSON.stringify(res), Date.now() - t);
const rects = await page.evaluate(() => window.__rects);
console.log(JSON.stringify(rects));
await browser.close();

