import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { startForCapture } from '/home/runner/work/_temp/omgithub-runtime/scripts/capture-start.mjs';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch(config.browser.launchOptions);
const modes = process.argv.slice(2);
for (const mode of modes) {
  const results = [];
  for (let i = 0; i < 3; i++) {
    const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
    try {
      await page.goto('http://localhost:3002', { waitUntil: 'load' });
      await page.waitForFunction(() => document.fonts.status === 'loaded');
      if (mode === 'nuke') await page.addStyleTag({ content: '*{backdrop-filter:none!important;filter:none!important;box-shadow:none!important;animation:none!important;transition:none!important}.screen-fx{background:none!important}' });
      if (mode === 'noeffects') await page.addStyleTag({ content: '*{backdrop-filter:none!important}.logo,.logo-smash{filter:none!important;animation:none!important}.screen-fx{background:none!important}.cta:hover{transform:none!important}.cta::after{display:none!important}' });
      if (mode === 'noscan') await page.addStyleTag({ content: '.screen-fx{background:radial-gradient(ellipse at 50% 48%, transparent 38%, rgba(2,4,10,.42) 78%, rgba(2,4,10,.78) 100%)!important}' });
      const t = Date.now();
      const r = await startForCapture(page, { enabled: true, selector: '', timeout: 4000 });
      results.push(`${r.clicked ? 'ok' : r.reason}@${Date.now() - t}`);
    } catch (e) {
      results.push(`throw@${Date.now()}`);
    }
    await page.close();
  }
  console.log(mode, results.join(' | '));
}
await browser.close();

