for (const mode of ['control', 'static']) {
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.addInitScript(() => {
    window.__f = [];
    let last = performance.now();
    const t0 = last;
    function tick(now) { window.__f.push([Math.round(now - t0), Math.round(now - last)]); last = now; requestAnimationFrame(tick); }
    requestAnimationFrame(tick);
  });
  if (mode === 'static') await page.addInitScript(() => {
    const s = document.createElement('style');
    s.textContent = '*{animation:none!important;filter:none!important;backdrop-filter:none!important}.screen-fx{background:none!important}';
    document.addEventListener('DOMContentLoaded', () => document.head.appendChild(s));
  });
  const t = Date.now();
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  console.log(mode, 'load', Date.now() - t);
  await page.waitForFunction(() => document.fonts.status === 'loaded');
  console.log(mode, 'fonts', Date.now() - t);
  await page.waitForTimeout(2500);
  const f = await page.evaluate(() => window.__f);
  console.log(mode, 'frames', f.length, 'first', JSON.stringify(f.slice(0, 8)), 'maxgap', Math.max(...f.map((x) => x[1])), 'last', JSON.stringify(f.slice(-4)));
  await page.close();
}
await browser.close();
EOF
